list_discount_profiles.code:
import (
	"fmt"
)

resp, err := client.DiscountProfiles().ListDiscountProfiles(ctx, map[string]any{"sort": "name", "dir": "asc"}, nil)
if err != nil {
	log.Fatal(err)
}
body := resp.Map().(map[string]any)
for _, row := range body["discount_profiles"].([]any) {
	profile := row.(map[string]any)
	fmt.Println(profile["id"], profile["name"], profile["type"], profile["is_active"])
}
pagination := body["pagination"].(map[string]any)
fmt.Println(pagination["total"], pagination["has_next"])

