import (
	"fmt"
)

resp, err := client.DiscountProfiles().CreateDiscountProfile(ctx, map[string]any{
	"name": "Spring 40 Off", "type": "offer_coupon", "discount_details_type": "amount",
	"amount_details": map[string]any{
		"type": "single", "apply_to": "total_order", "single_amount": 40, "single_amount_type": "PERCENT",
	},
	"is_active": true, "start_date": "2026-11-06 09:30:00", "is_specify_end_date": true, "end_date": "2026-11-16 18:00:00",
	"is_apply_coupon_code": true, "default_coupon_code": "SPRING40", "is_maximum_use_total": true, "maximum_use_count": 100,
